(()=>{const e=()=>{if(!("IntersectionObserver"in window))return;const t=document.querySelectorAll(".home-story__content"),e=new IntersectionObserver(t=>{t.forEach(t=>{if(!t.isIntersecting||t.intersectionRatio<.55)return;const n=t.target.querySelector(".home-story__content");if(e.unobserve(t.target),!n)return;n.classList.add("home-story--revealed"),window.setTimeout(()=>{n.classList.remove("home-story--waiting","home-story--revealed")},1300)})},{threshold:.55});t.forEach(t=>{const n=t.closest(".home-panel");if(!n)return;t.classList.add("home-story--waiting"),e.observe(n)})};document.readyState==="loading"?document.addEventListener("DOMContentLoaded",e,{once:!0}):e()})()